package typegen

import (
	"bytes"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/chucklehead-dev/gotogether/internal/skip"
)

// names.qnt's generated file is namestypes/names_types.go, whose test
// decodes the renamed names' values: the file is what the model generates
// now (GOTOGETHER_UPDATE_GOLDEN=1 writes it again), and its renames are
// the documented ones.
func TestNames(t *testing.T) {
	skip.Quint(t)
	tc, err := Typecheck(t.Context(), "quint", "testdata/names.qnt")
	if err != nil {
		t.Fatal(err)
	}
	m, err := Read(tc, "names")
	if err != nil {
		t.Fatal(err)
	}
	src, err := Generate(m, Options{Package: "namestypes", From: "../testdata/names.qnt"})
	if err != nil {
		t.Fatal(err)
	}
	golden := filepath.Join("namestypes", "names_types.go")
	if os.Getenv("GOTOGETHER_UPDATE_GOLDEN") == "1" {
		if err := os.WriteFile(golden, src, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	have, err := os.ReadFile(golden)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(have, src) {
		t.Errorf("%s is stale: go generate ./internal/typegen/namestypes (or GOTOGETHER_UPDATE_GOLDEN=1 go test ./internal/typegen/)\nwant:\n%s", golden, src)
	}
	text := string(src)
	for _, want := range []string{
		"type State_ struct {",                 // the model's own State keeps its name
		"type State struct {",                  //
		"type Item_ struct {",                  // lib's Item, after the main module's
		"Li      Item_         `itf:\"li\"`",   // and l::Item resolves to it
		"Ab_     int    `itf:\"Ab\"`",          // fields that collide once exported
		"Hidden  int    `itf:\"_hidden\"`",     // a leading underscore dropped
		"Func    bool   `itf:\"func\"`",        // a Go keyword, exported: none
		"Tag_ int    `itf:\"Tag\"`",            // the variant named Tag
		"CmdTag_ CmdTag = \"Tag\"",             // its constant, after the tag type
		"ModeFast_ Mode = \"Fast\"",            // a constant after a type of its name
		"type Shape = itf.Value",               // variants Decode cannot tell apart
		"ByPoint map[Point]int",                // a record key: a Go map
		"Note    *string       `itf:\"note\"`", // Option[str], not MaybeItem (Option[Item]), whose node id it shares
		"type MaybeItem = *Item",
		"Key   *int",                            // an Option key: pairs
		"no Go type here: Option[a].",           // polymorphic
		"// gotogether:type lib::Item ",         // an import's type in the digests
		"// Code generated by gotogether types", // the header Go recognises
	} {
		if !strings.Contains(text, want) {
			t.Errorf("no %q in:\n%s", want, text)
		}
	}
	// the digests are the file's, and name each change
	entries, ok := FileEntries(src)
	if !ok || !slices.Equal(entries, m.Digests()) {
		t.Errorf("FileEntries = %v, %v; want %v", entries, ok, m.Digests())
	}
}

// Changes names each type or variable added, removed or changed, sorted.
func TestChanges(t *testing.T) {
	file := []Entry{{"type", "Item", "1"}, {"type", "Old", "2"}, {"var", "n", "3"}}
	model := []Entry{{"type", "Item", "9"}, {"type", "New", "4"}, {"var", "n", "3"}, {"var", "m", "5"}}
	got := Changes(model, file)
	want := []string{"type Item changed", "type New added", "type Old removed", "var m added"}
	if !slices.Equal(got, want) {
		t.Errorf("Changes = %v, want %v", got, want)
	}
	if c := Changes(model, model); len(c) != 0 {
		t.Errorf("no change: %v", c)
	}
	if _, ok := FileEntries([]byte("package x\n")); ok {
		t.Error("a file without the header has entries")
	}
}

// A Quint name becomes an exported Go name; a taken one takes trailing
// underscores; a package name must be a Go identifier and no keyword.
func TestGoNames(t *testing.T) {
	for in, want := range map[string]string{"byName": "ByName", "by_name": "By_name", "_x": "X", "__": "X", "lib::Item": "Item", "Event": "Event", "état": "État"} {
		if got := exported(in); got != want {
			t.Errorf("exported(%q) = %q, want %q", in, got, want)
		}
	}
	taken := map[string]bool{}
	if a, b, c := claim(taken, "A"), claim(taken, "A"), claim(taken, "A"); a != "A" || b != "A_" || c != "A__" {
		t.Errorf("claims: %s %s %s", a, b, c)
	}
	for _, bad := range []string{"type", "func", "9x", "a-b", "_", ""} {
		if err := CheckPackage(bad); err == nil || !strings.Contains(err.Error(), "-package") {
			t.Errorf("CheckPackage(%q) = %v", bad, err)
		}
	}
	if err := CheckPackage("model"); err != nil {
		t.Error(err)
	}
}

// A main module the spec lacks is refused, naming the spec's modules.
func TestReadNamesTheModules(t *testing.T) {
	tc := []byte(`{"modules":[{"name":"a","declarations":[]},{"name":"b","declarations":[]}]}`)
	if _, err := Read(tc, "c"); err == nil || !strings.Contains(err.Error(), "no module c: name its main module with -main (its modules: a, b)") {
		t.Errorf("Read: %v", err)
	}
}
